function message(e:unknown){return e instanceof Error?e.message:"This action could not be completed.";}
function InputIssue({issue,retry}:{issue:MediaProblem;retry?:()=>void}) {
  return <div className="input-issue" role="alert"><strong>{issue.title}</strong><p>{issue.message}</p>{issue.standalone&&<a href={window.location.href} target="_blank" rel="noopener noreferrer">Open full studio</a>}{retry&&<button onClick={retry}>Retry tracking</button>}{issue.detail&&<details><summary>Error details</summary><code>{issue.code}: {issue.detail}</code></details>}</div>;
}

