  function playAnimation(name:string,loop=true){setEditorEnabled(false);setConfig(c=>({...playClip(c,name,loop),performance:{...c.performance,mode:"live",playing:false}}));}
  function selectPower(id:PowerId){if(engine.current)engine.current.powers.remaining=0;const play=powerAnimations&&!!info?.animations.length&&id!=="none";if(play)setEditorEnabled(false);setConfig(c=>{const next=powerPreset(c,id,play);return play?{...next,performance:{...next.performance,mode:"live",playing:false}}:next;});}
  async function connectRemote(){
    if(remoteStarting.current||remote.current&&!remoteStatus.expired)return;
    remote.current?.dispose();remote.current=null;remoteStarting.current=true;setRemoteBusy(true);tracking.current?.stop();setCameraIssue(null);takeLiveTracking();
    const generation=++remoteGeneration.current;setRemoteStatus({connected:false,transport:"waiting",camera:false});
    try{const host=await RemoteHost.create({
      frame:frame=>{engine.current?.setTracking(frame);if(performance.now()-lastCoverage.current>300){setCoverage(trackingCoverage(frame,configRef.current.tracking.confidence));lastCoverage.current=performance.now();}},
      preview:()=>engine.current?.previewImage()||null,
      snapshot:()=>{const {info,ready,stats,busy}=remoteContext.current,c=configRef.current;return {model:c.characters.items.find(p=>p.id===c.characters.selected)?.name||info?.name||"SGX Robot",animations:info?.animations||[],mode:c.mode,power:c.power.id,animation:c.avatar.animation,frozen:c.frozen,face:stats.face,ready:ready&&!busy,hands:c.puppet,pads:padViews(),tracking:{hands:c.tracking.hands,body:c.tracking.pose?c.tracking.bodyMode:"off"},performance:(()=>{const clip=c.performance.clips.find(p=>p.id===c.performance.clip);return clip?{name:clip.name,time:Math.min(clip.duration,engine.current?.posePlayer.time||0),duration:clip.duration,playing:c.performance.playing}:undefined;})()};},
      command:command=>{const e=engine.current,context=remoteContext.current;if(!e||!context.ready||context.busy)throw new Error("El personaje todavía está cargando.");const c=command.type==="tracking"?padRuntime.current.releaseAll(configRef.current):configRef.current,next=applyRemoteCommand(c,command,{animations:context.info?.animations||[],face:(e.raw.faceDetected??!!e.raw.face?.length)&&performance.now()-e.raw.time<650,calibrate:()=>e.calibrate(),frame:p=>e.frameCamera(p),burst:()=>e.powers.burst(c.power.id),clearPower:()=>{e.powers.remaining=0;},pad:performPad});if(command.type==="tracking"||command.type==="animation"||command.type==="reset"||command.type==="power"&&next.performance.mode==="live")setEditorEnabled(false);if(command.type==="reset")padRuntime.current.clear();if(command.type==="tracking"){e.cancelHandRigTest();e.editor.setEnabled(false);}commitConfig(next);},status:setRemoteStatus,
    });if(generation!==remoteGeneration.current){void host.revoke().catch(()=>{});return;}remote.current=host;setPair(host.pairing);toast.success("Escanea el QR desde tu teléfono");}catch(e){if(generation===remoteGeneration.current){setPair(null);setRemoteStatus({connected:false,transport:"waiting",camera:false,error:message(e)});}}finally{if(generation===remoteGeneration.current){remoteStarting.current=false;setRemoteBusy(false);}}
  }
  async function disconnectRemote(){const host=remote.current;if(!host)return;commitConfig(padRuntime.current.releaseHolds(configRef.current));setRemoteBusy(true);try{try{await host.revoke();}catch(e){if(!(e instanceof RemoteError&&e.status===410))throw e;}remote.current=null;setPair(null);setRemoteStatus({connected:false,transport:"waiting",camera:false});engine.current?.setTracking({signals:{},face:[],faceDetected:false,hands:[],pose:[],inference:0,time:performance.now()});}catch(e){setRemoteStatus(s=>({...s,connected:false,expired:true,error:message(e)}));}finally{setRemoteBusy(false);}}
  function layerVisible(id:string,name:string){const flag=info?.robot?robotPartFlag(name):undefined;return !config.avatar.hidden.includes(id)&&(!flag||config.robot[flag]);}
  function toggleLayer(id:string,name:string,visible:boolean){const flag=info?.robot?robotPartFlag(name):undefined;setConfig(c=>({...c,avatar:{...c.avatar,hidden:visible?c.avatar.hidden.filter(n=>n!==id):[...c.avatar.hidden,id]},robot:flag&&visible?{...c.robot,[flag]:true}:c.robot}));}
